CREATE COLUMN TABLE "UAT_JBF2"."NDBS_BGC_OBDE" ("DocEntry" INTEGER CS_INT NOT NULL , "BudgetGroup" NVARCHAR(50), "BudgetYear" NVARCHAR(50), "Department" NVARCHAR(50), "ObjectType" NVARCHAR(50), "ObjectID" INTEGER CS_INT, "ObjectLine" INTEGER CS_INT, "BaseType" NVARCHAR(50), "BaseID" INTEGER CS_INT, "BaseLine" INTEGER CS_INT, "Amount" DECIMAL(21,6) CS_FIXED, "BudgetType" NVARCHAR(50), "ValueDate" NVARCHAR(50), "BudgetStatus" NVARCHAR(50), "PrimaryObjectType" NVARCHAR(50), "PrimaryObjectID" INTEGER CS_INT, "PrimaryObjectLine" INTEGER CS_INT, "BF" NVARCHAR(1), "TYPE" NVARCHAR(10), PRIMARY KEY ("DocEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "UAT_JBF2"."NDBS_BGC_OBDE" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$Department$BudgetGroup$BudgetYear$BudgetStatus$BudgetType$','Department','BudgetGroup','BudgetYear','BudgetStatus','BudgetType'));
CREATE INDEX "IDX_OBDE_BUDGET_QUERY" ON "UAT_JBF2"."NDBS_BGC_OBDE" ( "Department" ASC, "BudgetGroup" ASC, "BudgetYear" ASC, "BudgetStatus" ASC, "BudgetType" ASC )